#!/bin/sh
# Full reference render set as produced on 2026-11-08 (about 2 h 20 min on the M4 Pro with the GPU shared).
# Resumable: rerunning continues from reference/out/accum (a pair already at its spp is just re-saved).
# Do not edit this file while it runs (sh reads scripts incrementally).
set -e
cd "$(dirname "$0")/.."
uv run python reference/render_ref.py --set reference --spp 12288
uv run python reference/render_ref.py below_golden backlit_golden --spp 24576
uv run python reference/render_ref.py --set heldback --spp 6144
uv run python reference/render_ref.py --mode single front_noon side_noon backlit_golden below_noon distant_sunset side_sunset --spp 16384
uv run python reference/contact_sheet.py
